alter table public.community_people add column phone text, add column birth_date date, add column started_on date, add column stopped_on date, add column role_description text, add column avatar_url text;
do $$ declare legacy record; source_link public.migration_source_links%rowtype; raw jsonb; new_id uuid; sent_on date; birth_on date; started date; stopped date; response text; begin
 for legacy in select * from public.legacy_records where deleted_at is null and converted_target_table is null and payload->>'board_name'='[CRM] Outreach pipeline' order by created_at,id for update loop
  raw:=coalesce(legacy.payload->'raw_fields','{}'::jsonb);response:=coalesce(raw->>'Reactie','');begin sent_on:=nullif(raw->>'Datum verzonden','')::date;exception when others then sent_on:=null;end;
  select * into source_link from public.migration_source_links where target_table='legacy_records' and target_id=legacy.id order by imported_at desc limit 1;if source_link.id is null then raise exception 'missing source link %',legacy.id;end if;
  insert into public.partners(organization_id,name,partner_type,status,priority,last_contact,notes,owner_id,created_by) values(legacy.organization_id,trim(legacy.title),'sponsor',case when lower(response)='negatief' then 'rejected' when lower(response) in('positief','in behandeling') then 'conversation' when lower(coalesce(legacy.source_status,''))='verzonden' then 'waiting' else 'prospect' end,'normal',sent_on,nullif(concat_ws(E'\n',case when coalesce(raw->>'Label','')<>'' then 'Contactkanaal: '||(raw->>'Label') end,case when coalesce(raw->>'Persoon','')<>'' then 'Opgevolgd door: '||(raw->>'Persoon') end,case when response<>'' then 'Reactie: '||response end),''),source_link.imported_by,source_link.imported_by) returning id into new_id;
  if sent_on is not null or response<>'' then insert into public.partner_interactions(organization_id,partner_id,interaction_type,occurred_at,summary,created_by) values(legacy.organization_id,new_id,case when lower(coalesce(raw->>'Label','')) like '%mail%' then 'email' else 'note' end,coalesce(sent_on::timestamp at time zone 'Europe/Brussels',now()),concat_ws(' · ',nullif(raw->>'Label',''),nullif(response,'')),source_link.imported_by);end if;
  insert into public.migration_source_links(organization_id,source_system,source_workspace,source_board_id,source_item_id,target_table,target_id,source_url,source_payload,imported_by) values(legacy.organization_id,source_link.source_system,source_link.source_workspace,source_link.source_board_id,source_link.source_item_id,'partners',new_id,source_link.source_url,source_link.source_payload,source_link.imported_by);
  update public.legacy_records set converted_target_table='partners',converted_target_id=new_id,converted_at=now(),lifecycle='completed',updated_at=now() where id=legacy.id;
 end loop;
 for legacy in select * from public.legacy_records where deleted_at is null and converted_target_table is null and payload->>'board_name'='[PEOPLE] People master' order by created_at,id for update loop
  raw:=coalesce(legacy.payload->'raw_fields','{}'::jsonb);begin birth_on:=nullif(raw->>'Birthday','')::date;exception when others then birth_on:=null;end;begin started:=nullif(raw->>'Gestart','')::date;exception when others then started:=null;end;begin stopped:=nullif(raw->>'Gestopt','')::date;exception when others then stopped:=null;end;
  select * into source_link from public.migration_source_links where target_table='legacy_records' and target_id=legacy.id order by imported_at desc limit 1;if source_link.id is null then raise exception 'missing source link %',legacy.id;end if;
  insert into public.community_people(organization_id,display_name,handle,person_type,status,email,discord_handle,onboarding_status,phone,birth_date,started_on,stopped_on,role_description,avatar_url,owner_id,created_by) values(legacy.organization_id,trim(legacy.title),nullif(raw->>'Nickname',''),case when lower(coalesce(raw->>'Rol','')) like '%moderator%' then 'moderator' else 'crew' end,case when lower(coalesce(legacy.source_status,'')) like 'inactief%' then 'inactive' else 'active' end,nullif(raw->>'Email',''),nullif(raw->>'Nickname',''),'completed',nullif(raw->>'Phone',''),birth_on,started,stopped,nullif(raw->>'Rol',''),nullif(raw->>'Bestanden',''),source_link.imported_by,source_link.imported_by) returning id into new_id;
  insert into public.migration_source_links(organization_id,source_system,source_workspace,source_board_id,source_item_id,target_table,target_id,source_url,source_payload,imported_by) values(legacy.organization_id,source_link.source_system,source_link.source_workspace,source_link.source_board_id,source_link.source_item_id,'community_people',new_id,source_link.source_url,source_link.source_payload,source_link.imported_by);
  update public.legacy_records set converted_target_table='community_people',converted_target_id=new_id,converted_at=now(),lifecycle='completed',updated_at=now() where id=legacy.id;
 end loop;
end $$;
